mapper.update:
UPDATE ainer_ai_task
SET status = #{newStatus}, updated_at = #{updatedAt}
WHERE id = #{id} AND status = #{expectedStatus}

UPDATE ainer_ai_task_run
SET status = #{status}, completed_at = #{completedAt}
WHERE id = #{id} AND status = #{expectedStatus}

UPDATE ainer_ai_task_run
SET status = 'FAILED', completed_at = #{healedAt}
WHERE id IN (
    SELECT id
    FROM ainer_ai_task_run
    WHERE status = 'RUNNING'
      AND started_at < #{startedBefore}
    ORDER BY started_at
    LIMIT #{limit}
    FOR UPDATE SKIP LOCKED
)
  AND status = 'RUNNING'

UPDATE ainer_ai_task
SET status = 'FAILED', updated_at = #{healedAt}
WHERE id IN (
    SELECT id
    FROM ainer_ai_task
    WHERE status = 'RUNNING'
      AND updated_at < #{updatedBefore}
    ORDER BY updated_at
    LIMIT #{limit}
    FOR UPDATE SKIP LOCKED
)
  AND status = 'RUNNING'
